<?php
defined( 'ABSPATH' ) || exit;

/** Gemeinsamer Backend-Katalog für öffentliche MGD-WordPress-Release-Pakete. */
if ( ! class_exists( 'MGD_WordPress_Plugin_Catalog' ) ) {
    final class MGD_WordPress_Plugin_Catalog {
        private const OWNER = 'MichaelGahnDESIGN';
        public function register( string $parent ): void { add_submenu_page( $parent, 'Weitere Plugins', 'Weitere Plugins', 'install_plugins', 'mgd-wordpress-plugin-catalog', array( $this, 'page' ) ); add_action( 'admin_post_mgd_wordpress_plugin_install', array( $this, 'install' ) ); }
        /** Fragt ausschließlich im Backend GitHub-Repositories des Eigentümers ab und cached sechs Stunden. */
        public function items( bool $refresh = false ): array {
            $cache = $refresh ? false : get_transient( 'mgd_wordpress_plugin_catalog_v1' ); if ( is_array( $cache ) ) return $cache;
            $response = wp_remote_get( 'https://api.github.com/users/' . self::OWNER . '/repos?type=owner&per_page=100&sort=updated', array( 'timeout' => 10, 'headers' => array( 'Accept' => 'application/vnd.github+json', 'User-Agent' => 'MGD-WordPress-Plugin-Catalog/' . MGD_NOTIFICATION_VERSION ) ) );
            if ( is_wp_error( $response ) || 200 !== wp_remote_retrieve_response_code( $response ) ) return array(); $items = array();
            foreach ( (array) json_decode( wp_remote_retrieve_body( $response ), true ) as $repo ) { $name = (string) ( $repo['name'] ?? '' ); if ( empty( $repo['private'] ) && 1 === preg_match( '/^MGD-.+-WordPress$/', $name ) ) { $item = $this->release( $name, (string) ( $repo['description'] ?? '' ) ); if ( $item ) $items[] = $item; } }
            set_transient( 'mgd_wordpress_plugin_catalog_v1', $items, 6 * HOUR_IN_SECONDS ); return $items;
        }
        private function release( string $repo, string $description ): ?array {
            $key = 'mgd_release_' . md5( $repo ); $release = get_transient( $key );
            if ( ! is_array( $release ) ) { $response = wp_remote_get( 'https://api.github.com/repos/' . self::OWNER . '/' . rawurlencode( $repo ) . '/releases/latest', array( 'timeout' => 10, 'headers' => array( 'Accept' => 'application/vnd.github+json', 'User-Agent' => 'MGD-WordPress-Plugin-Catalog/' . MGD_NOTIFICATION_VERSION ) ) ); if ( is_wp_error( $response ) || 200 !== wp_remote_retrieve_response_code( $response ) ) return null; $release = json_decode( wp_remote_retrieve_body( $response ), true ); set_transient( $key, $release, 6 * HOUR_IN_SECONDS ); }
            $download = esc_url_raw( $release['assets'][0]['browser_download_url'] ?? '' ); if ( ! str_starts_with( $download, 'https://github.com/' . self::OWNER . '/' . $repo . '/releases/download/' ) ) return null;
            return array( 'repository' => $repo, 'description' => $description, 'version' => sanitize_text_field( $release['tag_name'] ?? '' ), 'download' => $download, 'installed' => $this->installed( $repo ) );
        }
        private function installed( string $repo ): bool { require_once ABSPATH . 'wp-admin/includes/plugin.php'; foreach ( get_plugins() as $plugin ) { if ( 'https://github.com/' . self::OWNER . '/' . $repo === untrailingslashit( (string) ( $plugin['UpdateURI'] ?? $plugin['PluginURI'] ?? '' ) ) ) return true; } return false; }
        public function page(): void { if ( ! current_user_can( 'install_plugins' ) ) wp_die( 'Nicht berechtigt.' ); $items = $this->items( ! empty( $_GET['refresh'] ) ); ?><div class="wrap"><h1>Weitere MGD WordPress-Plugins</h1><p>Automatisch aus öffentlichen <code>MGD-…-WordPress</code>-Repositories; Aktualisierung spätestens nach sechs Stunden oder sofort über den Button.</p><p><a class="button" href="<?php echo esc_url( add_query_arg( array( 'page' => 'mgd-wordpress-plugin-catalog', 'refresh' => 1 ), admin_url( 'admin.php' ) ) ); ?>">Liste aktualisieren</a></p><table class="widefat striped"><thead><tr><th>Plugin</th><th>Version</th><th>Beschreibung</th><th>Status</th><th>Aktion</th></tr></thead><tbody><?php foreach ( $items as $item ) : ?><tr><td><strong><?php echo esc_html( $item['repository'] ); ?></strong></td><td><?php echo esc_html( $item['version'] ); ?></td><td><?php echo esc_html( $item['description'] ); ?></td><td><?php echo $item['installed'] ? 'Installiert' : 'Nicht installiert'; ?></td><td><?php if ( ! $item['installed'] ) : ?><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><?php wp_nonce_field( 'mgd_plugin_catalog_install_' . $item['repository'] ); ?><input type="hidden" name="action" value="mgd_wordpress_plugin_install"><input type="hidden" name="repository" value="<?php echo esc_attr( $item['repository'] ); ?>"><button class="button button-primary">Installieren</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php }
        public function install(): void { if ( ! current_user_can( 'install_plugins' ) ) wp_die( 'Nicht berechtigt.' ); $repo = sanitize_text_field( wp_unslash( $_POST['repository'] ?? '' ) ); check_admin_referer( 'mgd_plugin_catalog_install_' . $repo ); foreach ( $this->items() as $item ) { if ( hash_equals( $item['repository'], $repo ) && ! $item['installed'] ) { require_once ABSPATH . 'wp-admin/includes/class-wp-upgrader.php'; ( new Plugin_Upgrader( new Automatic_Upgrader_Skin() ) )->install( $item['download'] ); break; } } wp_safe_redirect( admin_url( 'admin.php?page=mgd-wordpress-plugin-catalog' ) ); exit; }
    }
}
